                onClick = dispatch,
    private val output: (ScreenOutput) -> Unit,
) : ScreenComponent, ComponentContext by componentContext {
    private val store = instanceKeeper.getStore(key = "${screen.name}:${stableId.orEmpty()}") {
        ScreenStoreProvider(
            dependencies.storeFactory, dependencies.manager, screen, stableId, dependencies.mainContext,
        ).provide()
    }

    override val model: Value<ScreenModel> = StoreValue(store) { it.toModel() }

    init {
        val disposable = store.labels(observer(onNext = { label ->
            when (label) {
                is ScreenStore.Label.Completed -> output(ScreenOutput.Completed(label.command.operation, label.command.subjectId))
                is ScreenStore.Label.ConfirmationRequested -> output(
                    ScreenOutput.ConfirmationRequested(
                        sourceScreen = screen,
                        command = label.command,
                        destructiveOperation = requireNotNull(label.command.destructiveOperation),
                    ),
                )
            }
        }))
        lifecycle.subscribe(object : com.arkivanov.essenty.lifecycle.Lifecycle.Callbacks {
            override fun onDestroy() = disposable.dispose()
        })
    }

    override fun onAction(action: ScreenAction) {
        when (action) {
            ScreenAction.Back -> output(ScreenOutput.Back)
            ScreenAction.Retry -> store.accept(ScreenStore.Intent.Retry)
            is ScreenAction.Select -> store.accept(ScreenStore.Intent.Select(action.id))
            is ScreenAction.EditField -> store.accept(ScreenStore.Intent.EditField(action.fieldId, action.value))
            is ScreenAction.ChooseOption -> store.accept(ScreenStore.Intent.EditField(action.fieldId, action.optionId))
            is ScreenAction.Submit -> store.accept(ScreenStore.Intent.Submit(action.actionId))
            ScreenAction.CancelDraft -> store.accept(ScreenStore.Intent.CancelDraft)
            is ScreenAction.SetLayout -> store.accept(ScreenStore.Intent.SetLayout(action.mode))
            is ScreenAction.Execute -> {
                val destructiveOperation = action.command.destructiveOperation
                if (destructiveOperation == null) {
                    store.accept(ScreenStore.Intent.Execute(action.command))
                } else {
                    output(ScreenOutput.ConfirmationRequested(screen, action.command, destructiveOperation))
                }
            }
            is ScreenAction.ExecuteConfirmed -> {
                requireNotNull(action.command.destructiveOperation) { "Only classified destructive commands may use the confirmed path" }
                store.accept(ScreenStore.Intent.Execute(action.command))
            }
        }
    }
}

private fun ScreenStore.State.toModel(): ScreenModel {
    val contract = ScreenContractRegistry.contracts.getValue(screen)
    val sourceFields = snapshot.fields.ifEmpty { contract.fields }
    val fields = sourceFields.map { value -> value.copy(value = draftValues[value.id] ?: value.value) }
    val facts = snapshot.facts.ifEmpty { contract.facts }
    val actions = snapshot.actions.ifEmpty { contract.actions }
    return ScreenModel(
        screen = screen,
        loadState = when {
            loading -> LoadState.LOADING
            errorKey != null -> LoadState.ERROR
            ScreenVariant.EMPTY in contract.variants && snapshot.items.isEmpty() -> LoadState.EMPTY
            else -> LoadState.CONTENT
        },
        titleKey = titleKey(screen),
        items = snapshot.items,
        selectedItemId = snapshot.selectedItemId,
        primaryActionKey = snapshot.primaryActionKey,
        errorKey = errorKey,
        permissionState = snapshot.permissionState,
        conflictResolutionKeys = snapshot.conflictResolutionKeys,
        offline = snapshot.offline,
        busy = busy,
        layoutMode = layoutMode,
        showInlineAdSlot = snapshot.showInlineAdSlot,
        destructiveConfirmationKey = snapshot.destructiveConfirmationKey,

    private sealed interface Action { data object Observe : Action }
    private sealed interface Msg {
        data class Loaded(val snapshot: ScreenSnapshot) : Msg
        data class Committed(val snapshot: ScreenSnapshot) : Msg
        data class Selected(val id: String) : Msg
        data class Busy(val value: Boolean) : Msg
        data class Failed(val key: TextKey) : Msg
        data class Layout(val mode: com.sedsoftware.sproutpace.component.LayoutMode) : Msg
        data class FieldEdited(val fieldId: ScreenFieldId, val value: String) : Msg
        data class ValidationFailed(val errors: Map<ScreenFieldId, TextKey>) : Msg
        data object DraftCancelled : Msg
    }

    private inner class ExecutorImpl :
        CoroutineExecutor<ScreenStore.Intent, Action, ScreenStore.State, Msg, ScreenStore.Label>(mainContext) {
        private var observation: Job? = null
        private val inFlight = mutableSetOf<String>()
        private val completedKeys = mutableSetOf<String>()

        override fun executeAction(action: Action) { observe() }

        override fun executeIntent(intent: ScreenStore.Intent) {
            when (intent) {
                ScreenStore.Intent.Retry -> observe()
                is ScreenStore.Intent.Select -> dispatch(Msg.Selected(intent.id))
                is ScreenStore.Intent.EditField -> dispatch(Msg.FieldEdited(intent.fieldId, intent.value))
                is ScreenStore.Intent.Submit -> submit(intent.actionId)
                ScreenStore.Intent.CancelDraft -> dispatch(Msg.DraftCancelled)
                is ScreenStore.Intent.SetLayout -> dispatch(Msg.Layout(intent.mode))
                is ScreenStore.Intent.Execute -> executeValidated(intent.command)
            }
        }

        private fun submit(actionId: com.sedsoftware.sproutpace.component.ScreenActionId) {
            when (
                val preparation = ScreenContractRegistry.prepareCommand(
                    screen = screen,
                    actionId = actionId,
                    currentSubjectId = state().stableId ?: state().snapshot.selectedItemId,
                    draft = state().draftValues,
                )
            ) {
                is CommandPreparation.Invalid -> dispatch(Msg.ValidationFailed(preparation.errors))
                is CommandPreparation.Ready -> {
                    if (preparation.command.destructiveOperation == null) {
                        executeValidated(preparation.command)
                    } else {
                        publish(ScreenStore.Label.ConfirmationRequested(preparation.command))
                    }
                }
            }
        }

        private fun executeValidated(command: ScreenCommand) {
            val operation = ScreenContractRegistry.contracts.getValue(screen).operations[command.operation]
            if (operation == null) {
                dispatch(Msg.ValidationFailed(mapOf(ScreenFieldId("id") to TextKey("state_error_body"))))
                return
            }
            if (!operation.itemTargeted) {
                execute(command)
                return
            }
            val draft = command.arguments.mapKeys { (name, _) -> ScreenFieldId(name) }
            when (
                val preparation = ScreenContractRegistry.prepareCommand(
                    screen = screen,
                    actionId = com.sedsoftware.sproutpace.component.ScreenActionId(command.operation),
                    currentSubjectId = command.subjectId,
                    draft = draft,
                )
            ) {
                is CommandPreparation.Invalid -> dispatch(Msg.ValidationFailed(preparation.errors))
                is CommandPreparation.Ready -> {
                    val exactTarget = state().snapshot.items.any { item ->
                        item.commands.any { target ->
                            target.operation == command.operation && target.subjectId == command.subjectId
                        }
                    }
                    if (operation.itemTargeted && !exactTarget) {
                        dispatch(Msg.ValidationFailed(mapOf(ScreenFieldId("id") to TextKey("state_error_body"))))
                    } else if (
                        preparation.command.operation != command.operation ||
                        preparation.command.subjectId != command.subjectId ||
                        preparation.command.arguments != command.arguments
                    ) {
                        dispatch(Msg.ValidationFailed(mapOf(ScreenFieldId("id") to TextKey("state_error_body"))))
                    } else {
                        execute(command)
                    }
                }
            }
        }

        private fun observe() {
            observation?.cancel()
            observation = scope.launch {
                manager.watch(screen, stableId).collectLatest { dispatch(Msg.Loaded(it)) }
            }
        }

        private fun execute(command: ScreenCommand) {
            if (command.deduplicationKey in completedKeys || !inFlight.add(command.deduplicationKey)) return
            scope.launch {
                dispatch(Msg.Busy(true))
                manager.execute(screen, command).unwrap(
                    onSuccess = {
                        dispatch(Msg.Committed(it))
                        completedKeys += command.deduplicationKey
                        publish(ScreenStore.Label.Completed(command))
                    },
                    onFailure = { dispatch(Msg.Failed(TextKey("error_operation_failed"))) },
                )
                inFlight -= command.deduplicationKey
                dispatch(Msg.Busy(false))
            }
        }
    }

